#define TASK_H

#include <iostream>
#include <chrono>
#include <functional>
#include <thread>

class task {
public:
	task() {
	}

	task(std::function<void(void)> func, const long &interval) {
		m_func = func;
		m_interval = interval;
	}

	virtual ~task() {
		stop();
	}

	void start() {
		m_running = true;
		m_stopped = false;

		m_thread = std::thread([&]() {
			while(m_running) {
				auto delta = std::chrono::steady_clock::now() + std::chrono::milliseconds(m_interval);
				m_func();
				std::this_thread::sleep_until(delta);
			}

			m_stopped = true;
		});

		m_thread.detach();
	}

	void stop() {
		if(!m_running) {
			return;
		}

		m_running = false;
		while(!m_stopped) {
			std::this_thread::sleep_for(std::chrono::milliseconds(10));
		}
	}

	void restart() {
		stop();
		start();
	}

	bool is_running() {
		return m_running;
	}

private:
	long m_interval;
	bool m_running;
	bool m_stopped;
	std::thread m_thread;
	std::function<void(void)> m_func;
};

#endif /* TASK_H */
"}

